document.getElementById('minify-btn').addEventListener('click', () => {
  const input = document.getElementById('input-js').value.trim();

  if (!input) {
    alert('Veuillez coller votre code JavaScript avant de minifier.');
    return;
  }

  // Minification basique (sans parser avancé)
  let minified = input
    .replace(/\/\/.*(?=\n)/g, '')              // Supprimer les commentaires //
    .replace(/\/\*[\s\S]*?\*\//g, '')          // Supprimer les commentaires /* ... */
    .replace(/\s*([=;{}(),:+\-*/<>])\s*/g, '$1') // Supprimer les espaces autour des symboles
    .replace(/\n|\r/g, '')                     // Supprimer les retours à la ligne
    .replace(/\s+/g, ' ')                      // Réduire les espaces multiples
    .trim();

  // Affichage du résultat
  document.getElementById('output-js').value = minified;

  // Statistiques
  const beforeSize = input.length;
  const afterSize = minified.length;
  const saved = beforeSize - afterSize;
  const percent = beforeSize > 0 ? ((saved / beforeSize) * 100).toFixed(2) : '0';

  document.getElementById('result-stats').textContent =
    `Taille avant : ${beforeSize} caractères | Après : ${afterSize} caractères | Économisé : ${saved} caractères (${percent}%)`;

  // Graphique avec Chart.js
  const ctx = document.getElementById('chart-stats').getContext('2d');

  if (window.myChart) {
    window.myChart.destroy();
  }

  window.myChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: ['Avant', 'Après'],
      datasets: [{
        label: 'Taille (caractères)',
        data: [beforeSize, afterSize],
        backgroundColor: ['#ffc107', '#007bff'] // jaune et bleu
      }]
    },
    options: {
      responsive: true,
      plugins: {
        legend: { display: false }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            stepSize: Math.ceil(beforeSize / 5)
          }
        }
      }
    }
  });
});

document.getElementById('reset-btn').addEventListener('click', () => {
  document.getElementById('input-js').value = '';
  document.getElementById('output-js').value = '';
  document.getElementById('result-stats').textContent = '';
  if (window.myChart) {
    window.myChart.destroy();
  }
});

document.getElementById('copy-btn').addEventListener('click', () => {
  const output = document.getElementById('output-js').value;
  if (!output) {
    alert('Rien à copier, la zone de résultat est vide.');
    return;
  }

  if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
    navigator.clipboard.writeText(output)
      .then(() => alert('JavaScript minifié copié dans le presse-papiers !'))
      .catch(err => alert('Erreur lors de la copie : ' + err));
  } else {
    const textArea = document.createElement('textarea');
    textArea.value = output;
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand('copy');
      alert('JavaScript minifié copié dans le presse-papiers !');
    } catch (err) {
      alert('Erreur lors de la copie : ' + err);
    }
    document.body.removeChild(textArea);
  }
});

document.getElementById('download-btn').addEventListener('click', () => {
  const output = document.getElementById('output-js').value;
  if (!output) {
    alert('Aucun JavaScript à télécharger.');
    return;
  }

  const blob = new Blob([output], { type: 'application/javascript' });
  const link = document.createElement('a');
  const date = new Date().toISOString().slice(0, 10);

  link.href = URL.createObjectURL(blob);
  link.download = `js-minifie-${date}.js`;

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
});
